public protocol ProjectProtocol: AnyObject, Sendable {
    
    /**
     * Stops overriding a file's disk contents.
     */
    func clearText(path: String) 
    
    func click(page: UInt32, x: Double, y: Double)  -> ClickTarget?
    
    func compile()  -> CompileReport
    
    func complete(path: String, offset: UInt64, explicit: Bool)  -> Completions?
    
    func cursorPositions(path: String, offset: UInt64)  -> [PreviewPosition]
    
    func definition(path: String, offset: UInt64)  -> DefinitionTarget?
    
    func displayList(page: UInt32)  -> Data
    
    /**
     * Resolves a click in the preview (page is 0-based, coordinates in pt).
     * Where the text at a cursor position ended up in the preview.
     * Autocompletion at a UTF-16 offset of a file.
     * Hover information at a UTF-16 offset of a file.
     * Go-to-definition for the identifier at a UTF-16 offset.
     * Exports the last successful compilation as PDF.
     */
    func exportPdf(destination: String) throws 
    
    /**
     * Exports one page as PNG at the given pixels per point.
     */
    func exportPng(page: UInt32, pixelPerPt: Float, destination: String) throws 
    
    /**
     * Exports one page as SVG.
     */
    func exportSvg(page: UInt32, destination: String) throws 
    
    /**
     * The display list of a page of the last successful compilation.
     * Outlines of glyphs in a font referenced by a display list.
     */
    func glyphOutlines(font: UInt32, glyphs: [UInt16])  -> Data
    
    /**
     * An image referenced by a display list.
     */
    func image(id: UInt32)  -> ImageData?
    
    /**
     * Forgets cached disk contents after external changes.
     */
    func invalidateFiles() 
    
    /**
     * Chooses the file that is compiled.
     */
    func setMain(path: String) throws 
    
    /**
     * Supplies known Universe packages for import completions.
     */
    func setPackageIndex(entries: [UniversePackage]) 
    
    /**
     * Provides the editor's (possibly unsaved) text for a file.
     */
    func setText(path: String, text: String) 
    
    func tooltip(path: String, offset: UInt64)  -> TooltipInfo?
    
}
