public enum ClickTarget: Equatable, Hashable {
    
    case source(path: String, offset: UInt64
    )
    case url(url: String
    )
    case position(page: UInt32, x: Double, y: Double
    )





}

#if compiler(>=6)
extension ClickTarget: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeClickTarget: FfiConverterRustBuffer {
    typealias SwiftType = ClickTarget

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClickTarget {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .source(path: try FfiConverterString.read(from: &buf), offset: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 2: return .url(url: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .position(page: try FfiConverterUInt32.read(from: &buf), x: try FfiConverterDouble.read(from: &buf), y: try FfiConverterDouble.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ClickTarget, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .source(path,offset):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(path, into: &buf)
            FfiConverterUInt64.write(offset, into: &buf)
            
        
        case let .url(url):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(url, into: &buf)
            
        
        case let .position(page,x,y):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(page, into: &buf)
            FfiConverterDouble.write(x, into: &buf)
            FfiConverterDouble.write(y, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeClickTarget_lift(_ buf: RustBuffer) throws -> ClickTarget {
    return try FfiConverterTypeClickTarget.lift(buf)
